import{_ as n,l,o as e,c as s,v as r,p as i,x as o,d as B,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Qwen2.5 技术报告","description":"","frontmatter":{"title":"Qwen2.5 技术报告","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen25-report.md","filePath":"llm/qwen25-report.md","lastUpdated":1789023840000}'),h={name:"llm/qwen25-report.md"};function u(T,a,m,c,d,P){const t=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="qwen2-5-技术报告" tabindex="-1">Qwen2.5 技术报告 <a class="header-anchor" href="#qwen2-5-技术报告" aria-label="Permalink to &quot;Qwen2.5 技术报告&quot;">​</a></h1><div class="epigraph"><p>Qwen2.5 把高质量预训练从 7 万亿扩到 18 万亿 token；后训练用逾百万条 SFT，再接离线 DPO 与在线 GRPO。</p><footer>—— Qwen Team，Qwen2.5 Technical Report，arXiv:2412.15115</footer></div><p><a href="/llm/qwen-evolution">Qwen 1.5 / 2 / 2.5 演进</a> 写家族差分；Coder / Math / 1M 各有专文。本篇对着 <strong>2412.15115</strong> 写 2.5 <strong>这一份报告</strong>里的可核对配方：稠密与云上 MoE 分家、缩放律用来调学习率而不是只定尺寸、两段预训练长度、SFT→DPO→GRPO 的后训练，以及 72B-Instruct 对标 Llama-3-405B 的叙事。架构与 Qwen2 相同——<a href="/llm/gqa">GQA</a>、<a href="/llm/swiglu">SwiGLU</a>、RoPE、<strong>保留 QKV bias</strong>、<a href="/llm/rmsnorm">RMSNorm</a>——不要把 Qwen3 的去 bias / QK-Norm 提前写进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Qwen2 开源档是 0.5B / 1.5B / 7B / 72B 加 57B-A14B MoE，预训练约 7T。缺的是中间部署点（3B / 14B / 32B）和「同样 72B 是否够厚」。2.5 的问题是：在<strong>不改解码器骨架</strong>的前提下，用 18T 与更重的后训练，让开源旗舰在知识、代码、数学、结构化输出上逼近大一个数量级的稠密模型，并用 Turbo / Plus 两条 API MoE 去打 GPT-4o-mini / GPT-4o 的价绩位置。</p><p>第二个问题是长生成与长窗口分开。2 的生成长度偏短；2.5 要把生成拉到约 8k，把常规 Instruct 推理窗口做到约 128k，并把 <strong>1M</strong> 只交给 Turbo 专线，避免每张 7B 卡都宣称百万上下文。</p><h3 id="开源稠密与-api-稀疏必须分列" tabindex="-1">开源稠密与 API 稀疏必须分列 <a class="header-anchor" href="#开源稠密与-api-稀疏必须分列" aria-label="Permalink to &quot;开源稠密与 API 稀疏必须分列&quot;">​</a></h3><p>开源：Base + Instruct，尺寸 <strong>0.5B、1.5B、3B、7B、14B、32B、72B</strong>，bf16 与多种量化，Hugging Face / ModelScope / Kaggle 上超过一百个制品。专有：Qwen2.5-Turbo（API 名如 <code>qwen-turbo-2024-11-01</code>）与 Qwen2.5-Plus，细粒度专家 + <strong>共享专家</strong>（继承 Qwen2-MoE 惯例），专家个数与激活量未写成与 3 代相同的 128/8 表，细节<strong>公开信息有限</strong>，只知它们用来对标 4o-mini / 4o 档。不要把 Turbo 的 1M 窗口写进 72B-Instruct 的模型卡。</p><p><span class="marginnote">词表主体约 151643，控制符扩到 22 个（含工具），全系列共享。换尺寸不必换 tokenizer；缺工具符则 JSON 调用会对不齐训练分布。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预训练数据从 7T 到 <strong>18T</strong>，侧重知识、代码、数学，并分阶段切换混合。用 Qwen2-Instruct 做质量过滤与领域配平：下调电商/社交模板页，上调科技与学术。缩放律在 44M–14B 稠密与小 MoE 上扫 <strong>batch (B) 与学习率 (\\mu)</strong>，再外推到 72B 与云上 MoE——报告明确：他们用缩放律选超参，而不只是选「给定 FLOP 的最优宽度」。MoE 的激活量与总量则调到能分别对上 14B / 72B 稠密的质量目标。</p><h3 id="长度课程-4k→32k-turbo-再四级加长" tabindex="-1">长度课程：4k→32k，Turbo 再四级加长 <a class="header-anchor" href="#长度课程-4k→32k-turbo-再四级加长" aria-label="Permalink to &quot;长度课程：4k→32k，Turbo 再四级加长&quot;">​</a></h3><p>除 Turbo 外，全体先在 4,096 上预训练，末期扩到 32,768，RoPE 基数 ABF 从 (10^4) 到 (10^6)。推理用 <a href="/llm/yarn">YaRN</a> 与 <a href="/llm/dual-chunk-attention">Dual Chunk Attention</a> 再四倍：常规约 <strong>131,072</strong>。Turbo 单独走 32k→65k→131k→262k，RoPE 基数 (10^7)，每档约 40% 满长、60% 短序列，再外推到 <strong>1M</strong>。后训练 SFT 对 Turbo 再加长样本，以免对齐洗掉长窗。</p><p>后训练三条：<strong>逾 100 万</strong>条 SFT（含最长约 8k 的生成、数学、带执行校验的代码、表格/JSON、多语），两 epoch、序列 32k 量级；然后对数学/代码/指令遵循等「有标准答案但奖励模型难打分」的域做离线 <a href="/llm/rafailov-dpo">DPO</a>（执行反馈与答案匹配造正负对）；在线 <a href="/llm/grpo-paper">GRPO</a> 用奖励模型，每查询采样 8 条，按分数方差排课程，全局 batch 2048。奖励模型的查询来自开源与更难的私有集，回复来自 SFT/DPO/RL 不同检查点与温度。</p>',14)),(e(),i(E,null,{default:o(()=>[p(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20D7%5B%22Qwen2%20%E7%9A%84%207T%20%E7%AE%A1%E7%BA%BF%22%5D%20--%3E%20D18%5B%22%E8%BF%87%E6%BB%A4%E9%85%8D%E5%B9%B3%20%E2%86%92%2018T%22%5D%0A%20%20SL%5B%22%E7%BC%A9%E6%94%BE%E5%BE%8B%EF%BC%9A%E6%89%AB%20B%20%E4%B8%8E%20LR%22%5D%20--%3E%20PT%5B%22%E7%A8%A0%E5%AF%86%200.5B%E2%80%9372B%20%2F%20%E4%BA%91%E4%B8%8A%20MoE%22%5D%0A%20%20D18%20--%3E%20PT%0A%20%20PT%20--%3E%20CTX%5B%224k%20%E2%86%92%2032k%20%2B%20ABF%22%5D%0A%20%20CTX%20--%3E%20SFT%5B%22%E7%99%BE%E4%B8%87%E7%BA%A7%20SFT%EF%BC%8C%E7%94%9F%E6%88%90%E8%87%B3%20~8k%22%5D%0A%20%20SFT%20--%3E%20DPO%5B%22%E7%A6%BB%E7%BA%BF%20DPO%22%5D%0A%20%20DPO%20--%3E%20GRPO%5B%22%E5%9C%A8%E7%BA%BF%20GRPO%22%5D%0A%20%20CTX%20--%3E%20TURBO%5B%22Turbo%EF%BC%9A32k%E2%86%92256k%20%E8%AF%BE%E7%A8%8B%20%E2%86%92%201M%20%E6%8E%A8%E7%90%86%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>报告评测叙事：72B-Instruct 在多项上对开源与部分专有有竞争力，并称可对照约 5 倍大的 Llama-3-405B-Instruct；14B-Instruct 接近 GPT-4o-mini；Turbo 训练/推理更便宜，却在多张表上超过 14B-Instruct。32B-Instruct 相对同尺寸 Gemma2-27B 与前代 Qwen2-57B-A14B，数学与代码跳得尤其明显——这被解释为 18T 里 STEM/代码配比，而不是新注意力。长上下文表上 Turbo 在 1M 针检索仍高，综合型长文档会随长度掉点，说明「能取回」和「能用上」仍要两张表。这些都是 2024-12 快照，不是 2025 年的 Qwen3 表。</p><p><span class="marginnote">SFT「一百万」是条数，不是 token 数，不得加进 18T。GRPO 的 8 样本与 DeepSeek-Math 论文同族，超参以 2.5 报告为准，不要把 R1 的配方倒填回来。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>18T 的机制是把 72B 继续推向欠拟合曲线的右侧，并靠配平避免「更多网页 = 更多导航模板」。骨架不变，意味着 KV 布局、bias、RoPE 实现可以沿用 2 的内核；质量差来自数据与对齐。GQA 使 128k 的缓存可服务；YaRN/DCA 是推理补丁，应用必须用匹配实现，否则 128k 只是配置谎言。</p><p>DPO 先处理可验证域，减少「奖励模型不会判对错」时的在线 RL 噪声；GRPO 再在偏好与开放性任务上用组内相对优势，避免单独价值网络。生成 8k 来自 SFT 显式加长，而不是上下文 128k 的自动副作用——窗口长不等于愿意写长。结构化输出与工具控制符把 JSON 当成一等格式，降低「聊天模型不会填表」的失败率。</p><h3 id="云上-moe-的机制是价绩-不是开源可复现" tabindex="-1">云上 MoE 的机制是价绩，不是开源可复现 <a class="header-anchor" href="#云上-moe-的机制是价绩-不是开源可复现" aria-label="Permalink to &quot;云上 MoE 的机制是价绩，不是开源可复现&quot;">​</a></h3><p>细粒度专家 + 共享专家让激活远小于总参数，API 按激活计价。没有公开与 Mixtral 同构的 8×top-2 表，就不能把 Turbo 画成 Mixtral 放大版。缩放律预测「多少激活对上 72B」是内部曲线；外部只看到产品对标 4o。Plus 的发布节奏以 API 名为准，报告里曾出现占位日期。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>QKV bias 仍在，与 Qwen3 不兼容。2.5-7B 默认不是 1M。MoE 权重基本不随 18T 稠密一起开源。18T 的版权与污染外部不可逐条审计。72B vs 405B 的「接近」依赖所选基准；人类偏好与长尾事实不一定同方向。专线 Math / Coder 仍更尖，基座只是「不再明显不会」。后训练里「结构化输入输出更好」依赖 SFT 里的表与 JSON，换一套自创 schema 仍会掉格式。在线 GRPO 的奖励模型若过拟合家族风格，会把多样性打掉——报告用多检查点、多温度采样来对冲，外部无法复现同一 RM。</p><p>工程上，32B / 72B 的 128k 服务仍受 KV 带宽限制；量化制品与 bf16 分数会分叉。工具调用必须带上 22 个控制符的模板。不要用 2.5 报告解释 Qwen3 的思考模式。</p><p><span class="marginnote">真实编号：arXiv:2412.15115。前代 Qwen2 为 2407.10671；Qwen1.5 以博客为主。1M 开源检查点见 <a href="/llm/qwen25-1m">Qwen2.5-1M</a>，不是每张 2.5 卡的默认。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>开源稠密 0.5B–72B，架构对齐 Qwen2（含 QKV bias）；预训练 18T；常规推理约 128k，Turbo 到 1M。</li><li>缩放律用于学习率与 batch；后训练为百万 SFT + DPO + GRPO；生成长度约 8k。</li><li>API MoE（Turbo / Plus）细粒度 + 共享专家，权重与专家表公开信息有限。</li><li>出处：Qwen Team，<em>Qwen2.5 Technical Report</em>，arXiv:2412.15115。家族对照见 <a href="/llm/qwen-evolution">演进</a>，下一代预训练见 <a href="/llm/qwen3-report">Qwen3 报告</a>。</li></ul>',13))])}const k=n(h,[["render",u]]);export{b as __pageData,k as default};
